CAT = "nzhamRegs"; SEG = "REG"
# Sources: Radiocommunications Regulations (General User Radio Licence for Amateur Radio
# Operators) Notice 2025 (in force 1 July 2025), RSM PIB 46 Issue 19.1 (July 2025), RSM
# "Get a certificate and/or callsign" page. See sources.md.

def dbw_to_w(dbw):
    return 10 ** (dbw / 10)

_w30 = dbw_to_w(30)
assert round(_w30) == 1000
_w60m = dbw_to_w(11.8)
assert round(_w60m) == 15
_w7 = dbw_to_w(7)
assert round(_w7) == 5

